{
  "status": "SUPPORTED",
  "task_summary": "Identify fastening components, perform fastening at workbench, and place tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The workpiece located at the marked workbench location that requires fastening.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "workpiece",
          "assembly",
          "plate"
        ],
        "required_properties": [
          "has fastening holes",
          "needs securing"
        ]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The fastener (e.g., screw, bolt) required to secure the workpiece.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "rivet"
        ],
        "required_properties": [
          "fits into target holes",
          "secure attachment"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement (e.g., screwdriver, wrench) used to drive the fastener.",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "drill",
          "hammer"
        ],
        "required_properties": [
          "can drive fastener"
        ]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The surface of the table where the target is located and where tools must be placed.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "desk",
          "bench"
        ],
        "required_properties": [
          "flat surface",
          "stable"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "component_fits_target",
        "relation": "fits_into",
        "participant_roles": [
          "compatible_component",
          "fastening_target"
        ]
      ,
        "required": true
      },
      {
        "id": "tool_drives_component",
        "relation": "drives_into",
        "participant_roles": [
          "fastening_tool",
          "compatible_component",
          "fastening_target"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "fasten_operation",
        "operation": "fasten",
        "participant_roles": [
          "fastening_tool",
          "compatible_component",
          "fastening_target"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "place_tool_operation",
        "operation": "place_tool",
        "participant_roles": [
          "fastening_tool",
          "workbench_surface"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "black rectangular object on table with yellow and blue parts",
          "visual_description": "A flat object with yellow and blue components sitting on the wooden table."
        }
      ]
      ,
      "workbench_surface": [
        {
          "label": "wooden table top",
          "visual_description": "The wooden surface of the desk/workbench."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "left_drawer",
        "visual_description": "Closed blue drawer under the left side of the table.",
        "reason": "Likely contains small hardware or tools."
      },
      {
        "id": "right_drawer",
        "label": "right_drawer",
        "visual_description": "Closed blue drawer under the right side of the table.",
        "reason": "Likely contains small hardware or tools."
      },
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "Closed blue cabinet standing on the right side of the table.",
        "reason": "Likely contains larger tools or supplies."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "blue_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
